"""The per-contract result: which clauses are missing, where an old company name still appears.

Built automatically right after a contract has been read, so the legal team never has to start anything.
Rules first (clause-coverage from ingest, name registry), then the full-contract AI cross-check on every
missing clause the corporate guideline requires and on every old-name mention. Without a model key the
rule result stands, marked as not cross-checked.
"""

import json
from datetime import datetime, timezone

from sqlalchemy.orm import Session

from app.audits.graph import LABELS
from app.audits.verify import verify
from app.config import settings
from app.ingest.classify import TAXONOMY
from app.models import Document

CERTAIN = 0.9
NEW_NAME = "Riverty GmbH"


def required_for(contract_type: str) -> set[str]:
    g = json.loads((settings.data_dir / "guidelines.json").read_text())
    return set(g.get("*", [])) | set(g.get(contract_type, []))


def build(session: Session, doc: Document, language: str = "de") -> dict:
    """Compute and store doc.report. Returns it."""
    doc.report = {"status": "running"}
    session.commit()
    try:
        report = _build(session, doc, language)
    except Exception as exc:  # the contract stays usable; the report says why it failed
        session.rollback()
        doc = session.get(Document, doc.id)
        report = {"status": "failed", "error": f"{type(exc).__name__}: {exc}"}
    doc.report = report
    session.commit()
    return report


def _build(session: Session, doc: Document, language: str) -> dict:
    pages = [(p.page_no, p.text) for p in sorted(doc.page_rows, key=lambda p: p.page_no)]
    required = required_for(doc.contract_type)
    best: dict[str, object] = {}
    for c in doc.clauses:
        if c.clause_type in TAXONOMY and (c.clause_type not in best or c.confidence > best[c.clause_type].confidence):
            best[c.clause_type] = c
    clauses = []
    for ct in TAXONOMY:
        c = best.get(ct)
        entry = {"clause_type": ct, "required": ct in required, "verified": False}
        if c is not None and c.confidence >= CERTAIN:
            entry.update(status="present", page=c.page_no, quote=c.text[:240])
        elif c is not None:  # labelled, but not confidently: let the cross-check decide when it matters
            entry.update(status="present", page=c.page_no, quote=c.text[:240])
            if ct in required:
                v = verify(pages, f"The contract contains a {LABELS[ct]} clause (heading: '{c.heading}').", language)
                if v is not None:
                    entry["verified"] = True
                    if v.verdict == "refuted":
                        entry.update(status="missing", page=None, quote="", reason=v.reasoning)
                    elif v.verdict == "partial":
                        entry.update(status="partial", reason=v.reasoning, page=v.page or c.page_no, quote=(v.quote or c.text)[:240])
        else:
            entry.update(status="missing", page=None, quote="")
            if ct in required:
                v = verify(pages, f"The contract contains no {LABELS[ct]} clause.", language)
                if v is not None:
                    entry["verified"] = True
                    if v.verdict == "refuted":
                        entry.update(status="present", page=v.page or None, quote=v.quote[:240], reason=v.reasoning)
                    elif v.verdict == "partial":
                        entry.update(status="partial", page=v.page or None, quote=v.quote[:240], reason=v.reasoning)
                    else:
                        entry["reason"] = v.reasoning
        clauses.append(entry)

    mentions = [e for e in doc.entities if e.kind == "our_entity_old" and not e.historical]
    seen, old_names = set(), []
    for e in sorted(mentions, key=lambda e: (e.page_no, e.name)):
        key = (e.page_no, e.name.lower())
        if key in seen:
            continue
        seen.add(key)
        old_names.append({"name": e.name, "page": e.page_no, "quote": e.context[:240], "fuzzy": e.confidence < 1})
    names_verified, names_reason = False, ""
    if old_names:
        names = sorted({m["name"] for m in old_names})
        v = verify(pages, f"The contract names {', '.join(repr(n) for n in names)} as an active contracting party "
                          f"(not merely a historical reference), so the name must be updated to '{NEW_NAME}'.", language)
        if v is not None:
            names_verified, names_reason = True, v.reasoning
            if v.verdict == "refuted":
                old_names = []
    historical = sorted({e.name for e in doc.entities if e.kind == "our_entity_old" and e.historical})

    missing_required = [c for c in clauses if c["status"] != "present" and c["required"]]
    return {
        "status": "ready",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "language": language,
        "cross_checked": settings.llm_enabled,
        "clauses": clauses,
        "old_names": old_names,
        "old_names_verified": names_verified,
        "old_names_reason": names_reason,
        "historical_names": historical,
        "summary": {"missing": len(missing_required), "partial": sum(1 for c in missing_required if c["status"] == "partial"),
                    "old_names": len(old_names), "unreadable": any(s["method"] == "tesseract" and s["confidence"] < 0.5 for s in doc.ingest_summary)},
    }

result.output:
export type PageSummary = { page: number; method: string; confidence: number; note: string }

export type Doc = {
  id: number
  filename: string
  title: string
  contract_type: string
  language: string
  input_type: string
  pages: number
  status: string
  error: string
  ingest_summary: PageSummary[]
  injection_suspected: boolean
  injection_note: string
  warnings: string[] // stages that had to fall back (e.g. provider outage)
  sha256: string
  clauses: number
  entities: number
}

export type Clause = {
  id: number
  ordinal: number
  page_no: number
  heading: string
  clause_type: string
  confidence: number
  method: string
  rule_label: string
  llm_label: string
  text: string
}

export type Entity = {
  name: string
  kind: string
  page_no: number
  historical: boolean
  context: string
  method: string
  confidence: number
}

export type DocDetail = Doc & {
  page_rows: { page_no: number; method: string; confidence: number; text: string }[]
  clause_rows: Clause[]
  entity_rows: Entity[]
}

export type Evidence = { page: number; quote: string }

export type Finding = {
  id: number
  audit_id: number
  document_id: number
  filename: string
  title: string
  verdict: string
  confidence: number
  method_chain: string[]
  evidence: Evidence[]
  reasoning: string
  review_status: string
  review_note: string
  reviewed_at: string | null
  storage_ref: string
  audit_kind: string
  audit_params: Record<string, string>
  class_key: string
  policy: Policy
}

/** Why a person did or did not have to look at a finding (see api/app/policy.py). */
export type Policy =
  | { kind: 'required'; reason: 'not_verified' | 'learning'; review_rate: number }
  | { kind: 'spot_check'; review_rate: number }
  | { kind: 'auto'; review_rate: number }
  | { kind: 'carried_over'; decision: 'approved' | 'rejected'; note: string; decided_at: string | null; finding_id: number }
  | Record<string, never>

export type PolicyClass = {
  class_key: string
  kind: string
  params: Record<string, string>
  decisions: number
  approved: number
  rejected: number
  since_rejection: number
  agreement: number | null
  review_rate: number
  automation_active: boolean
  findings: Record<string, number>
}

export type PolicyReport = {
  classes: PolicyClass[]
  rules: { min_decisions: number; min_agreement: number; tiers: [number, number][] }
}

export type Audit = {
  id: number
  kind: string
  params: Record<string, string>
  status: string
  summary: Record<string, number | string | boolean | Record<string, number>>
  created_at: string
  findings: number | Finding[]
}

export type Coverage = {
  taxonomy: string[]
  labels: Record<string, string>
  rows: {
    document_id: number
    filename: string
    title: string
    contract_type: string
    language: string
    cells: Record<string, { confidence: number; method: string; page: number; heading: string }>
    required: string[] // clause types the corporate guideline demands for this contract type
  }[]
}

export type Config = {
  llm_enabled: boolean
  provider: string // gemini | foundry | none
  ocr_provider: string // tesseract | document_intelligence
  document_source: string // local | sharepoint
  routing: { task: string; model: string; thinking: string; purpose: string }[]
  taxonomy: string[]
  embedding: { model: string; dim: number }
}

export type ChatResult = {
  answer: string
  mode: string
  citations: (Passage & { quote: string })[]
  passages: Passage[]
  scope: { document_id: number; title: string; counterparty: string }[] // contracts the question names
}

export type Passage = {
  index: number
  document_id: number
  filename: string
  title: string
  page: number
  clause_type: string
  heading: string
  text: string
  score: number
}

export type LogEntry = {
  id: number
  ts: string
  actor: string
  action: string
  target_type: string
  target_id: number
  details: Record<string, unknown>
}

async function request<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  if (!res.ok) throw new Error(`${res.status} ${await res.text()}`)
  return res.json()
}

const json = (body: unknown): RequestInit => ({
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(body),
})

export const api = {
  config: () => request<Config>('/api/config'),
  documents: () => request<Doc[]>('/api/documents'),
  document: (id: number) => request<DocDetail>(`/api/documents/${id}`),
  ingestSamples: () => request<{ queued: number }>('/api/documents/ingest-samples', { method: 'POST' }),
  upload: (file: File) => {
    const body = new FormData()
    body.append('file', file)
    return request<{ queued: number }>('/api/documents/upload', { method: 'POST', body })
  },
  coverage: () => request<Coverage>('/api/coverage'),
  guidelines: () => request<Record<string, string[]>>('/api/guidelines'),
  guidelineAudits: (contract_type: string, language: string) =>
    request<{ audits: number[] }>(`/api/audits/guideline?contract_type=${encodeURIComponent(contract_type)}&language=${language}`, { method: 'POST' }),
  sync: () => request<{ source: string; queued: boolean }>('/api/documents/sync', { method: 'POST' }),
